	rr=r.match(/= ?"([^"]+)"/g)
	for(i in rr){
	//	java.log(rr[i])
	 a=rr[i].match(/"(.*)"/)[1]
	 if(/L2Jv|\/book|javas|^g$/.test(a)){}else{text=a}
		}
text
}catch{
	java.getString("text")
}
</js>

